def predict_formula_1(min_v, max_v):
    # Original: min(r,c) parity
    result = [[0]*8 for _ in range(8)]
    for r in range(8):
        for c in range(8):
            if r == 0 or c == 0:
                result[r][c] = max_v
            else:
