                    result[r][c] = max_v
                else:
                    result[r][c] = min_v
    return result

def predict_formula_2(min_v, max_v):
    # Popcount(r) parity combined with popcount(c) parity
    def pc(n):
        return bin(n).count('1')
    result = [[0]*8 for _ in range(8)]
    for r in range(8):
        for c in range(8):
            if r == 0 or c == 0:
                result[r][c] = max_v
            elif pc(r) % 2 == 0 and pc(c) % 2 == 0:
                result[r][c] = max_v
            elif pc(r) % 2 != 0 and pc(c) % 2 != 0:
                result[r][c] = max_v
            else:
                result[r][c] = min_v
    return result

def predict_formula_3(min_v, max_v):
    # XOR parity
    result = [[0]*8 for _ in range(8)]
    for r in range(8):
        for c in range(8):
            if r == 0 or c == 0:
                result[r][c] = max_v
            else:
                if ((r ^ c) % 2) == 0:
                    result[r][c] = max_v
                else:
                    result[r][c] = min_v
    return result

def predict_formula_4(min_v, max_v):
    # Just use r * c
    result = [[0]*8 for _ in range(8)]
    for r in range(8):
        for c in range(8):
            if r == 0 or c == 0:
                result[r][c] = max_v
            else:
                prod = r * c
                if prod % 4 == 0:
                    result[r][c] = max_v
                else:
                    result[r][c] = min_v
    return result

